components.css:
.ds-primary-nav { background:var(--ground); color:var(--paper); font-family: var(--sans); font-size: 1.0625rem; line-height: 1.6; } .ds-primary-nav a { color:inherit; text-underline-offset:.3em; text-decoration-thickness:1px; } .ds-primary-nav { display: flex; gap: 32px; font-size: 17px; }
.ds-primary-nav a { text-decoration: none; }
.ds-primary-nav a[aria-current="true"] { color: var(--amber); text-decoration: underline; } :focus-visible { outline: 2px solid var(--amber); outline-offset: 5px; } @media(max-width:760px) { .ds-primary-nav { flex-wrap:wrap; gap:10px 20px; font-size:15px; } }

.ds-case-index { background:var(--ground); } .ds-case-index { display: flex; flex: 1; padding-top: 14px; min-width: 0; }
.ds-case-index a { flex: 1; min-width: 0; position: relative; text-align: center; padding: 34px 6px 0; text-decoration: none; font: 400 16px/1.5 var(--mono); color: var(--muted); }
.ds-case-index a::before { content: ""; width: 13px; height: 13px; border: 1px solid var(--paper); background: var(--ground); border-radius: 50%; position: absolute; top: 4px; left: calc(50% - 6.5px); z-index: 1; }
.ds-case-index a:not(:last-child)::after { content: ""; height: 1px; background: var(--muted); width: 100%; position: absolute; top: 10px; left: 50%; }
.ds-case-index a[aria-current="true"] { color: var(--amber); }
.ds-case-index a[aria-current="true"]::before { border-color: var(--amber); background: var(--amber); }
.ds-case-position { display: block; } :focus-visible { outline: 2px solid var(--amber); outline-offset: 5px; } @media(max-width:760px) { .ds-case-index { padding-top:0; } .ds-case-index a { font:400 12px/1.4 var(--sans); padding:26px 3px 0; overflow-wrap:anywhere; } .ds-case-position { font-family:var(--mono); font-size:11px; } }

.ds-case-card { font-family: var(--sans); font-size: 1.0625rem; line-height: 1.6; } .ds-case-card h2, .ds-case-card p { margin:0; } .ds-case-card { flex: 0 0 var(--card-width); min-width: 0; min-height: var(--card-height); padding: 44px 60px 38px; border-radius: 3px; color: var(--ink); background: var(--paper); scroll-snap-align: center; display: flex; flex-direction: column; color-scheme: light; }
.ds-case-card h2 { font: 700 68px/1.04 var(--display); letter-spacing: -.035em; max-width: 12ch; margin-bottom: 28px; text-wrap: initial; }
.ds-case-summary { font-size: 28px; line-height: 1.45; max-width: 51ch; } @media(max-width:760px) { .ds-case-card { min-height:540px; padding:28px 24px; } .ds-case-card h2 { font-size:clamp(2rem,8vw,3rem); line-height:1.1; max-width:15ch; margin-bottom:22px; } .ds-case-summary { font-size:18px; line-height:1.5; overflow-wrap:break-word; } }

.ds-diagram-stage { background:var(--paper); color:var(--ink); font:400 1.0625rem/1.6 var(--sans); }
.ds-case-diagram { margin: auto 0; padding-top: 22px; }
.ds-diagram-art { position: relative; display: grid; gap: 32px; align-items: center; min-height: 142px; font-size: 16px; line-height: 1.35; }
.ds-diagram-art strong { font-weight: 600; }
.ds-diagram-art svg { fill: none; stroke: currentColor; stroke-width: 1.5; overflow: visible; }
.ds-case-diagram figcaption { margin-top: 14px; font-size: 15px; line-height: 1.4; color: #625540; }
[data-diagram="observability"] .ds-diagram-art { grid-template-columns: 1fr 1.5fr; }
.ds-collection { border-bottom: 4px solid var(--amber); padding: 14px 0; }
.ds-collection svg { display: block; width: 100%; height: 40px; margin-bottom: 12px; }
.ds-destinations { border-left: 1px solid #9e610b; display: grid; gap: 14px; padding-left: 26px; }
.ds-destinations > div { position: relative; border-bottom: 1px solid var(--paper-line); padding-bottom: 8px; display: flex; justify-content: space-between; gap: 14px; flex-wrap: wrap; }
.ds-destinations > div::before { content: ""; position: absolute; top: 12px; right: 100%; width: 26px; height: 1px; background: #9e610b; }
.ds-destinations span { color: #625540; }
@media(max-width:760px) {
.ds-case-diagram { padding-top: 24px; margin-bottom: 22px; }
.ds-diagram-art { gap: 18px; font-size: 14px; min-height: 160px; }
.ds-case-diagram figcaption { font-size: 13px; }
[data-diagram="observability"] .ds-diagram-art { grid-template-columns: .8fr 1fr; }
.ds-destinations { padding-left: 16px; }
.ds-destinations > div { gap: 4px; }
.ds-destinations > div::before { width: 16px; }
}

.ds-diagram-stage { background:var(--paper); color:var(--ink); font:400 1.0625rem/1.6 var(--sans); }
.ds-case-diagram { margin: auto 0; padding-top: 22px; }
.ds-diagram-art { position: relative; display: grid; gap: 32px; align-items: center; min-height: 142px; font-size: 16px; line-height: 1.35; }
.ds-diagram-art strong { font-weight: 600; }
.ds-diagram-art svg { fill: none; stroke: currentColor; stroke-width: 1.5; overflow: visible; }
.ds-case-diagram figcaption { margin-top: 14px; font-size: 15px; line-height: 1.4; color: #625540; }
[data-diagram="delivery"] .ds-diagram-art { grid-template-columns: 1fr 2fr; }
.ds-delivery-owner svg { display: block; width: 100%; height: 48px; margin-top: 8px; }
.ds-release-sheet { border: 1px solid var(--paper-line); border-top: 4px solid var(--amber); padding: 12px 18px; }
.ds-release-sheet > span { color: #625540; font-size: 14px; }
.ds-release-sheet > div { display: flex; align-items: center; gap: 8px; margin-top: 8px; }
.ds-release-sheet svg { width: 20px; height: 20px; }
.ds-release-sheet .ds-release-target { border-top: 1px solid var(--paper-line); padding-top: 8px; justify-content: space-between; flex-wrap: wrap; }
.ds-release-target span { font: 400 14px/1.4 var(--mono); }
@media(max-width:760px) {
.ds-case-diagram { padding-top: 24px; margin-bottom: 22px; }
.ds-diagram-art { gap: 18px; font-size: 14px; min-height: 160px; }
.ds-case-diagram figcaption { font-size: 13px; }
[data-diagram="delivery"] .ds-diagram-art { grid-template-columns: 1fr; gap: 4px; }
.ds-delivery-owner { display: flex; align-items: center; gap: 12px; }
.ds-delivery-owner svg { width: 60px; height: 26px; margin: 0; }
.ds-release-sheet { padding: 10px 12px; }
}

.ds-diagram-stage { background:var(--paper); color:var(--ink); font:400 1.0625rem/1.6 var(--sans); }
.ds-case-diagram { margin: auto 0; padding-top: 22px; }
.ds-diagram-art { position: relative; display: grid; gap: 32px; align-items: center; min-height: 142px; font-size: 16px; line-height: 1.35; }
.ds-diagram-art strong { font-weight: 600; }
.ds-diagram-art svg { fill: none; stroke: currentColor; stroke-width: 1.5; overflow: visible; }
.ds-case-diagram figcaption { margin-top: 14px; font-size: 15px; line-height: 1.4; color: #625540; }
[data-diagram="network"] .ds-diagram-art { display: block; padding-top: 30px; }
.ds-policy-boundary { position: absolute; inset: 0 0 28px 50%; border: 1px solid #9e610b; background: #e8a33d12; }
.ds-policy-boundary strong { position: absolute; top: -11px; left: 12px; padding: 0 6px; background: var(--paper); font-size: 14px; }
.ds-traffic-lanes > div { display: grid; grid-template-columns: 1fr 1fr 1fr; align-items: center; gap: 12px; min-height: 40px; position: relative; }
.ds-traffic-lanes svg { width: 100%; height: 24px; }
.ds-allowed-lane strong { padding-right: 10px; }
.ds-blocked-lane svg { color: #92501b; stroke-width: 2; }
.ds-enforcement { margin-top: 16px; font: 400 13px/1.4 var(--mono); }
@media(max-width:760px) {
.ds-case-diagram { padding-top: 24px; margin-bottom: 22px; }
.ds-diagram-art { gap: 18px; font-size: 14px; min-height: 160px; }
.ds-case-diagram figcaption { font-size: 13px; }
.ds-traffic-lanes > div { gap: 8px; grid-template-columns: 1fr .6fr 1fr; min-height: 50px; }
.ds-policy-boundary { left: 50%; }
.ds-policy-boundary strong { left: 4px; font-size: 12px; }
.ds-enforcement { font-size: 11px; }
}

.ds-diagram-stage { background:var(--paper); color:var(--ink); font:400 1.0625rem/1.6 var(--sans); }
.ds-case-diagram { margin: auto 0; padding-top: 22px; }
.ds-diagram-art { position: relative; display: grid; gap: 32px; align-items: center; min-height: 142px; font-size: 16px; line-height: 1.35; }
.ds-diagram-art strong { font-weight: 600; }
.ds-diagram-art svg { fill: none; stroke: currentColor; stroke-width: 1.5; overflow: visible; }
.ds-case-diagram figcaption { margin-top: 14px; font-size: 15px; line-height: 1.4; color: #625540; }
[data-diagram="ai"] .ds-diagram-art { grid-template-columns: 1.2fr 1fr; }
.ds-tool-sources { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 20px; }
.ds-tool-sources span { border-bottom: 2px solid var(--amber); padding-bottom: 6px; font: 400 14px/1.4 var(--mono); }
.ds-evidence-sheet { border: 1px solid var(--paper-line); padding: 14px 20px; position: relative; }
.ds-evidence-sheet::before { content: ""; position: absolute; width: 32px; height: 1px; background: #9e610b; right: 100%; top: 50%; }
.ds-evidence-sheet span { font: 400 14px/1.4 var(--mono); }
.ds-evidence-sheet svg { width: 100%; height: 30px; margin-block: 12px; color: #9b8f7b; }
.ds-evidence-sheet strong { display: block; }
@media(max-width:760px) {
.ds-case-diagram { padding-top: 24px; margin-bottom: 22px; }
.ds-diagram-art { gap: 18px; font-size: 14px; min-height: 160px; }
.ds-case-diagram figcaption { font-size: 13px; }
[data-diagram="ai"] .ds-diagram-art { grid-template-columns: 1fr 1fr; }
.ds-tool-sources { margin-top: 14px; }
.ds-tool-sources span, .ds-evidence-sheet span { font-size: 12px; }
.ds-evidence-sheet { padding: 12px; }
.ds-evidence-sheet::before { width: 18px; }
}
